function C:UpdateContents(num)
  local text = String.Empty
  if EventManager.nowEnding == "Ending_Yami" then
    text = "Charisma"
    self._scrollRect.gameObject:GetComponent("RectTransform").offsetMin = NEW("Vector2", nil, 0, 0)
    self._buttonRoot:SetActive(false)
  elseif EventManager.nowEnding == "Ending_Ideon" then
    text = "Ideon"
    self._scrollRect.gameObject:GetComponent("RectTransform").offsetMin = NEW("Vector2", nil, 0, 0)
    self._buttonRoot:SetActive(false)
  elseif EventManager.isHorror then
    local status = StatusManager:GetStatus("DayIndex")
    local status2 = StatusManager:GetStatus("DayPart")
    if status == 26 then
      text = ((function() if (status2 ~= 0) then return "Horror_Day2_AfterHaishin" else return "Horror_Day2_BeforeHaishin" end end)())
    end
    if status == 27 then
      repeat
        local __sw1 = num
        if __sw1 == -1 then
          return
        elseif __sw1 == 0 then
          text = "Horror_Day3_first"
        elseif __sw1 == 1 then
          text = "Horror_Day3_second"
        else
          text = "Horror_Day3_third"
        end
      until true
    end
    self._scrollRect.gameObject:GetComponent("RectTransform").offsetMin = NEW("Vector2", nil, 0, 0)
    self._buttonRoot:SetActive(false)
  else
    text = self:ThreadRank(StatusManager:GetStatus("Follower"))
  end
  local text2 = NgoEx.SuretaiFromType(CONCAT("Suretai_", STR.TrimEnd(text, "1", "2", "3")), Settings.CurrentLanguage.Value)
  self._suretai.text = text2
  for _, item in EACH(NgoEx.KituneFromRank(text)) do
    self:GetResInstance(false):SetData(NgoEx.SystemTextFromType("Kitsune_Handle", Settings.CurrentLanguage.Value), item.ResNumber, NgoEx.KituneFromType(item.Id, Settings.CurrentLanguage.Value))
  end
  if EventManager.KituneJien ~= "" then
    self:GetResInstance(false):SetData(NgoEx.SystemTextFromType("Kitsune_Handle", Settings.CurrentLanguage.Value), 11, EventManager.KituneJien)
  end
end

function C:Jien()
  local resInstance = self:GetResInstance(true)
  resInstance:SetData(NgoEx.SystemTextFromType("Kitsune_Handle", Settings.CurrentLanguage.Value), Random.Range(0, 900) + 11, NgoEx.KituneFromType("Kitune_Ending_Charisma_12", Settings.CurrentLanguage.Value))
  self.input.text = ""
  resInstance.transform:SetAsLastSibling()
  AudioManager:PlaySeByType("SE_status_up", false)
  self._scrollRect:DOVerticalNormalizedPos(0, 4, false):SetEase("InQuad"):Play()
end

function C:CleanThread()
  do
    local num = self._content.childCount - 1
    while num > 1 do
      Object.Destroy(self._content:GetChild(num).gameObject)
      num = num - 1
    end
  end
end

function C:ThreadRank(follower)
  if follower > 500000 then
    if follower > 1000000 then
      return "Legend3"
    end
    if follower > 750000 then
      return "Legend2"
    end
    return "Legend1"
  end
  if follower > 100000 then
    if follower > 400000 then
      return "Angel3"
    end
    if follower > 200000 then
      return "Angel2"
    end
    return "Angel1"
  end
  if follower > 10000 then
    if follower > 80000 then
      return "Shuueki3"
    end
    if follower > 40000 then
      return "Shuueki2"
    end
    return "Shuueki1"
  end
  if follower > 5000 then
    return "Normal3"
  end
  if follower > 2000 then
    return "Normal2"
  end
  return "Normal1"
end

function C:AutoScroll()
  if not coroutine.isyieldable() then spawn(C.AutoScroll, self) return end
  self:UpdateContents(-1)
  DOTween.Sequence():OnStart(function()
    self._scrollRect.verticalNormalizedPosition = 1
    self.jienResAlpha.alpha = 0
  end):AppendInterval(1):Append(self._scrollRect:DOVerticalNormalizedPos(0, 4, false):SetEase("InQuad")):Append(self.jienResAlpha:DOFade(1, 2)):AppendInterval(1):AppendCallback(function()
    self:CleanThread()
  end):Play()
end

function C:GetResInstance(isJien)
  if isJien then
    return Object.Instantiate(self._AAResPrefabView, self._content)
  end
  if self.stockIndex < self._resStocks.Count then
    local kitsuneResView = IDX(self._resStocks, self.stockIndex)
    kitsuneResView.gameObject:SetActive(true)
    self.stockIndex = self.stockIndex + 1
    return kitsuneResView
  end
  return Object.Instantiate(self._kituneResPrefabView, self._content)
end

return C
